468	export async function acceptAdminMappingAndStage(
469		input: { batchId: number; mappings: AcceptedBatchColumnMapping[]; storageRoot?: string },
470		dependencies: AdminWorkflowDependencies = {}
471	): Promise<StageBatchResult> {
472		const db = dependencies.db || getDb();
473		const state = await loadAdminBatchWorkflow(input.batchId, { ...dependencies, db });
474		if (!state.profile || !state.definitionDrafts) {
475			throw new AdminBatchWorkflowError({
476				code: 'action-not-allowed',
477				message: 'The analyzed profile is required before accepting mappings.',
478				action: 'accept-and-stage',
479				retryable: false,
480				batchId: input.batchId
481			});
482		}
483		const paths = batchStoragePaths(input.batchId, input.storageRoot);
484		const collapsed = collapsedDimensions(state.definitionDrafts);
485		let accepted = state.acceptedMapping;
486		if (accepted) {
487			if (!sameAcceptedMappings(accepted, input.mappings, collapsed)) {
488				throw new AdminBatchWorkflowError({
489					code: 'mapping-immutable',
490					message: 'This batch already has an accepted mapping. Upload a new batch to correct it.',
491					action: 'accept-and-stage',
492					retryable: false,
493					batchId: input.batchId
494				});
495			}
496		} else {
497			const intake = await readBatchIntakeManifest(paths).catch((error) => {
498				throw workflowFailure(error, 'accept-and-stage', input.batchId, false);
499			});
500			accepted = createAcceptedMappingManifest({
501				batchId: input.batchId,
502				sourceIntegrity: intake.source.integrity,
503				mappings: input.mappings,
504				collapsedDimensions: collapsed
505			});
506			await persistAcceptedMappingArtifacts({
507				paths,
508				manifest: accepted,
509				stagingInput: createBatchStagingInput(accepted)
510			});
511		}
512		try {
513			return await (dependencies.stage || stageBatch)(
514				{ batchId: input.batchId, storageRoot: input.storageRoot },
515				{ db }
516			);
517		} catch (error) {
518			throw workflowFailure(error, 'accept-and-stage', input.batchId, true);
519		}
520	}
